package com.lindum.mlkit.vision.posedetectorimport android.graphics.Bitmapimport android.graphics.BitmapFactoryimport android.graphics.Colorimport android.os.Buildimport android.os.Environmentimport android.os.Handlerimport android.util.Logimport android.widget.ImageViewimport androidx.annotation.RequiresApiimport com.google.android.gms.tasks.OnFailureListenerimport com.google.android.gms.tasks.OnSuccessListenerimport com.google.mlkit.vision.common.InputImageimport com.google.mlkit.vision.pose.Poseimport com.google.mlkit.vision.pose.PoseDetectionimport com.google.mlkit.vision.pose.accurate.AccuratePoseDetectorOptionsimport com.lindum.mlkit.vision.CameraXLivePreviewActivityimport com.lindum.mlkit.vision.CameraXLivePreviewActivity.Companion.poseEntityListimport com.lindum.mlkit.vision.result.TrainingResultimport com.orhanobut.logger.Loggerimport java.io.ByteArrayInputStreamimport java.io.ByteArrayOutputStreamimport java.io.Fileimport java.io.FileInputStreamimport java.io.FileNotFoundExceptionimport java.io.FileOutputStreamimport java.io.IOExceptionimport java.io.InputStream/** * @author MarkGosling * @date 2022/2/4 8:09 */class ProcessImage(var imageView: ImageView?) {    var resultBitmap: Bitmap? = null    @Volatile    var poseType: String? = null    var tempTips: String = ""    init {        warnPart = ArrayList<IntArray>()    }    @RequiresApi(api = Build.VERSION_CODES.LOLLIPOP)    fun processImage() {        val mHandler2 = Handler()        val r2: Runnable = object : Runnable {            override fun run() {                Log.e("Image", "执行中")                val sdPath = Environment.getExternalStorageDirectory().getPath()                val imagePath = File(sdPath + "/AiTrainer")                if (!imagePath.exists()) {                    imagePath.mkdir()                }                val files = imagePath.listFiles() // 读取                if (files == null) {                    return                }                if (!CameraXLivePreviewActivity.isEnd) {                    Log.e("Image", CameraXLivePreviewActivity.nowPoseIndex.toString() + "")                    for (file in files) {                        val fileName = file.getName()                        if (fileName.contains(".jpg")) {                            val poseNameIndex =                                fileName.split("-".toRegex()).dropLastWhile { it.isEmpty() }                                    .toTypedArray()[0].toInt()                            poseType = fileName.split("-".toRegex()).dropLastWhile { it.isEmpty() }                                .toTypedArray()[2]                            if (CameraXLivePreviewActivity.nowPoseIndex - 1 == poseNameIndex) {                                Log.e("ProcessImage", fileName)                                var fis: FileInputStream? = null                                try {                                    fis = FileInputStream(file.getPath())                                } catch (e: FileNotFoundException) {                                    e.printStackTrace()                                }                                val bitmap = BitmapFactory.decodeStream(fis)                                drawLandMark(bitmap, poseNameIndex)                                // 处理完之后将原图片删除                                file.delete()                            }                            if (CameraXLivePreviewActivity.isEnd) {                                Log.e("ProcessImage", fileName)                                var fis: FileInputStream? = null                                try {                                    fis = FileInputStream(file.getPath())                                } catch (e: FileNotFoundException) {                                    e.printStackTrace()                                }                                val bitmap = BitmapFactory.decodeStream(fis)                                drawLandMark(bitmap, poseNameIndex)                                // 处理完之后将原图片删除                                file.delete()                            }                        }                    }                    Log.e("BitmapListSize", bitmapList.size.toString() + "")                }                if (!CameraXLivePreviewActivity.isEnd) {                    mHandler2.postDelayed(this, 1000)                }            }        }        mHandler2.post(r2)    }    fun isPathContainJPEG(path: String): Boolean {        val file = File(path)        val files: Array<File>? = checkNotNull(file.listFiles())        for (f in files!!) {            if (f.getName().contains(".jpg")) {                return true            }        }        return false    }    fun Bitmap2IS(bm: Bitmap): InputStream {        val baos = ByteArrayOutputStream()        bm.compress(Bitmap.CompressFormat.JPEG, 100, baos)        return ByteArrayInputStream(baos.toByteArray())    }    @RequiresApi(api = Build.VERSION_CODES.LOLLIPOP)    fun drawLandMark(bitmap: Bitmap, poseNameIndex: Int) {        val options =            AccuratePoseDetectorOptions.Builder()                .setDetectorMode(AccuratePoseDetectorOptions.SINGLE_IMAGE_MODE)                .build()        val poseDetector = PoseDetection.getClient(options)        val image = InputImage.fromBitmap(bitmap, 0)        poseDetector.process(image)            .addOnSuccessListener(                OnSuccessListener { pose: Pose? ->                    // 当人在图像中时                    if (pose!!.getAllPoseLandmarks().size != 0) {                        tempTips = ""                        warnPart.clear()                        val landmarkList = pose.getAllPoseLandmarks()                        val drawLandmarkTools = DrawLandmarkTools(bitmap)                        // 人体关键的监测                        val poseAngleDetector = PoseAngleDetector(pose)                        resultBitmap = drawLandmarkTools.drawAllLandmark(                            landmarkList,                            Color.WHITE,                            14,                            Color.GREEN,                            8                        )                        // 动作模式： 普通模式 1 严格模式 2                        // 普通模式 待定 todo                        // 如果严格模式，则要求每个部位都要精准才算一个有效动作                        val mode = 2                        // 获取监测的动作实体                        val poseEntity = poseEntityList!!.get(poseNameIndex)                        // 获取监测部位列表 todo                        val monitoringList = poseEntity.getMonitoringPosePartList()                        // 固定部位列表                        val fixedPartList: MutableList<PosePart> = ArrayList<PosePart>()                        // 动态部位列表                        val dynamicPart: MutableList<PosePart> = ArrayList<PosePart>()                        // 将固定部位和动态部位分别筛选出来                        for (part in monitoringList) {                            if (part.getPoseType() == 0) fixedPartList.add(part)                            if (part.getPoseType() == 1) dynamicPart.add(part)                        }                        // 判断是否全部满足固定部位标准                        for (part in fixedPartList) {                            val partIndex = part.getPoseIndex()                            // 当前帧的角度                            val nowFrameAngle: Int                            // 自定义角度的情况                            if (partIndex == -1) {                                nowFrameAngle =                                    poseAngleDetector.getAnyAngleBy3Point(part.getThreePointIndex())                            } else {                                nowFrameAngle =                                    poseAngleDetector.getPoseAngleFromPartIndex(partIndex)                            }                            if (!(nowFrameAngle > part.getFixedRange()[0] && nowFrameAngle < part.getFixedRange()[1])) {                                // 固定部位不满足标准的时候报红，那么动态部位什么情况下报红呢？ todo 我觉得是超过这个动态的总范围就报红                                addWarnPart(partIndex)                            }                            if (partIndex != -1) {                                if (nowFrameAngle < part.getFixedRange()[0]) {                                    tempTips += "，" + getPartName(partIndex) + "角度要大一点"                                }                                if (nowFrameAngle > part.getFixedRange()[1]) {                                    tempTips += "，" + getPartName(partIndex) + "角度小一点"                                }                            }                        }                        // 判断是否全部满足动态部位标准                        for (part in dynamicPart) {                            val partIndex = part.getPoseIndex()                            // 当前帧的角度                            val nowFrameAngle: Int                            // 自定义角度的情况                            if (partIndex == -1) {                                nowFrameAngle =                                    poseAngleDetector.getAnyAngleBy3Point(part.getThreePointIndex())                            } else {                                nowFrameAngle =                                    poseAngleDetector.getPoseAngleFromPartIndex(partIndex)                            }                            // 下蹲                            if (poseType!!.contains("down") && !(nowFrameAngle > part.getSecondStandardRange()[0] && nowFrameAngle < part.getSecondStandardRange()[1])) {                                addWarnPart(partIndex)                                Logger.e("不合格")                            }                            if (poseType!!.contains("up") && !(nowFrameAngle > part.getFirstStandardRange()[0] && nowFrameAngle < part.getFirstStandardRange()[1])) {                                addWarnPart(partIndex)                            }                            if (partIndex != -1) {                                if (nowFrameAngle < part.getFirstStandardRange()[0]) {                                    tempTips += "，" + getPartName(partIndex) + "角度要大一点"                                }                                if (nowFrameAngle > part.getSecondStandardRange()[1]) {                                    tempTips += "，" + getPartName(partIndex) + "角度小一点"                                }                                tempTips += "测试建议"                            }                        }                        resultBitmap = drawLandmarkTools.drawAllLandmark(                            landmarkList,                            Color.WHITE,                            14,                            Color.GREEN,                            8                        )                        // 将不标准的部位标出                        if (warnPart.size != 0) {                            var w = ""                            for (i in warnPart.indices) {                                val tempArray: IntArray = warnPart.get(i)                                w += tempArray.contentToString()                                for (j in 0..<tempArray.size - 1) {                                    val poseLandmark1 = pose.getPoseLandmark(tempArray[j])                                    val poseLandmark2 = pose.getPoseLandmark(tempArray[j + 1])                                    checkNotNull(poseLandmark1)                                    checkNotNull(poseLandmark2)                                    val pointF1 = poseLandmark1.getPosition()                                    val pointF2 = poseLandmark2.getPosition()                                    Logger.e("有异常点")                                    resultBitmap =                                        drawLandmarkTools.drawLine(pointF1, pointF2, Color.RED, 9)                                }                            }                        }                        if (warnPart.size == 0) {                            return@OnSuccessListener                        }                        val sdPath = Environment.getExternalStorageDirectory().getPath()                        //                                    Log.e("Tips", poseNameIndex + "-" + tempTips);                        // 裁剪图片//                                    resultBitmap = drawLandmarkTools.cutImage(landmarkList,resultBitmap);//                                    imageView.setImageBitmap(resultBitmap);                        transferData(                            poseEntityList!!.get(poseNameIndex)                                .getPoseName(), tempTips, resultBitmap                        )                        //                                    saveBitmap(CameraXLivePreviewActivity.getPoseEntityList().get(poseNameIndex).getPoseName(), tempTips, resultBitmap, sdPath + "/AAABBB/" + CameraXLivePreviewActivity.getPoseEntityList().get(poseNameIndex).getPoseName() + "-" + random.nextInt() + ".jpg");//                                    // 判断是否全部满足动态部位第一个标准//                                    for (PosePart part : dynamicPart) {//                                        int partIndex = part.getPoseIndex();//                                        // 当前帧的角度//                                        int nowFrameAngle;//                                        // 自定义角度的情况//                                        if (partIndex == -1) {//                                            nowFrameAngle = poseAngleDetector.getAnyAngleBy3Point(part.getThreePointIndex());//                                        }//                                        // 常规部位角度情况//                                        else {//                                            nowFrameAngle = poseAngleDetector.getPoseAngleFromPartIndex(partIndex);//                                        }//                                        // 判断当前的角度是否满足第一个标准//                                        if (!(nowFrameAngle > part.getFirstStandardRange()[0] && nowFrameAngle < part.getFirstStandardRange()[1])) {//                                            dynamicPartJudge1 = false;//                                        }//                                        if (dynamicPartJudge1 && !CameraXLivePreviewActivity.isPose1() && fixedPartJudge) {//                                            CameraXLivePreviewActivity.addCount();//                                            CameraXLivePreviewActivity.setPose1(true);//                                        }//                                        // 判断当前的角度是否满足第二个标准//                                        if (!(nowFrameAngle > part.getSecondStandardRange()[0] && nowFrameAngle < part.getSecondStandardRange()[1])) {//                                            dynamicPartJudge2 = false;//                                        }//                                        if (dynamicPartJudge2 && CameraXLivePreviewActivity.isPose1() && fixedPartJudge) {//                                            CameraXLivePreviewActivity.addCount();//                                            CameraXLivePreviewActivity.setPose1(false);//                                        }//                                    }                    }                })            .addOnFailureListener(                OnFailureListener { e: Exception? ->                    Log.e(TAG, "处理图像失败")                })    }    /**     * 获取部位名称     *     * @param index 身体部位索引     * @return 身体部位名称     */    fun getPartName(index: Int): String {        val partNames = arrayOf<String>(            "",            "右手腕",            "右胳膊肘",            "右手臂与肩膀",            "左手臂与肩膀",            "左胳膊肘",            "左手腕",            "右腿与身体",            "左腿与身体",            "右膝盖",            "左膝盖",            "右脚腕",            "左脚腕"        )        return partNames[index]    }    //读取指定目录下的所有TXT文件的文件名    private fun getFileName(files: Array<File>?): String {        var str = ""        if (files != null) {    // 先判断目录是否为空，否则会报空指针            for (file in files) {                if (file.isDirectory()) { //检查此路径名的文件是否是一个目录(文件夹)                    Log.i(                        "zeng", ("若是文件目录。继续读1"                                + file.getName() + file.getPath())                    )                    getFileName(file.listFiles())                    Log.i(                        "zeng", ("若是文件目录。继续读2"                                + file.getName() + file.getPath())                    )                } else {                    val fileName = file.getName()                    if (fileName.endsWith(".jpg")) {                        val s = fileName.substring(0, fileName.lastIndexOf("."))                        Log.i("zeng", "文件名txt：：   " + s)                        str += fileName.substring(0, fileName.lastIndexOf(".")) + "\n"                    }                }            }        }        return str    }    companion object {        private const val TAG = "ProcessImage"        private var warnPart: MutableList<IntArray> = arrayListOf()        var bitmapList: MutableList<Bitmap?> = TrainingResult.Companion.resultImage        var tipsList: MutableList<String?> = TrainingResult.Companion.resultTips        var nameList: MutableList<String?> = TrainingResult.Companion.resultName        fun transferData(name: String?, tempTips: String?, bitmap: Bitmap?) {            Logger.e("分析结果数组" + bitmapList.size)            bitmapList.add(bitmap)            tipsList.add(tempTips)            nameList.add(name)        }        /**         * 保存bitmap到本地         *         * @param bitmap Bitmap         */        fun saveBitmap(name: String?, tempTips: String?, bitmap: Bitmap, path: String) {            bitmapList.add(bitmap)            tipsList.add(tempTips)            nameList.add(name)            val savePath: String            val filePic: File?            if (Environment.getExternalStorageState() == Environment.MEDIA_MOUNTED) {                savePath = path            } else {                Log.e("tag", "saveBitmap failure : sdcard not mounted")                return            }            try {                filePic = File(savePath)                if (!filePic.exists()) {                    filePic.getParentFile().mkdirs()                    filePic.createNewFile()                }                val fos = FileOutputStream(filePic)                bitmap.compress(Bitmap.CompressFormat.JPEG, 100, fos)                fos.flush()                fos.close()            } catch (e: IOException) {                Log.e("tag", "saveBitmap: " + e.message)                return            }            Log.i("tag", "saveBitmap success: " + filePic.getAbsolutePath())        }        fun addWarnPart(partIndex: Int) {            // 添加报错的部位            if (partIndex == 12) {                warnPart.add(intArrayOf(25, 27, 31))            } else if (partIndex == 11) {                warnPart.add(intArrayOf(26, 28, 32))            } else if (partIndex == 10) {                warnPart.add(intArrayOf(23, 25, 27))            } else if (partIndex == 9) {                warnPart.add(intArrayOf(24, 26, 28))            } else if (partIndex == 8) {                warnPart.add(intArrayOf(11, 23, 25))            } else if (partIndex == 7) {                warnPart.add(intArrayOf(12, 24, 26))            } else if (partIndex == 6) {                warnPart.add(intArrayOf(13, 15, 19))            } else if (partIndex == 5) {                warnPart.add(intArrayOf(11, 13, 15))            } else if (partIndex == 4) {                warnPart.add(intArrayOf(13, 11, 23))            } else if (partIndex == 3) {                warnPart.add(intArrayOf(14, 12, 24))            } else if (partIndex == 2) {                warnPart.add(intArrayOf(12, 14, 16))            } else if (partIndex == 1) {                warnPart.add(intArrayOf(20, 16, 14))            }        }    }}